 rid=add('amp-result-'+stem,'result',name+' reported endpoint',{'printed_value':value,'numeric_value':value,'metric':metric,'metric_direction':'lower' if unit=='seconds' else 'higher','unit':unit,'uncertainty':uncertainty,'source_locator':locator,'missing_metadata':missing,'review':review},src,[('evaluation',eid)]);return eid,rid
